package com.crypto.laplace.api;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import com.crypto.binance.client.BinanceFuturesClient;import com.crypto.common.enums.PositionSide;import com.crypto.laplace.execution.*;import com.crypto.laplace.model.*;import com.crypto.laplace.persistence.*;import java.math.BigDecimal;import java.util.List;import org.junit.jupiter.api.Test;
class LaplaceVariantApiServiceTest{
 @Test void closedPnlRemainsInTotalWhenNoPositionsAreOpenAndOtherTableIsUntouched(){var t=mock(LaplacePaperPositionRepository.class);var f=mock(LaplaceInvertedFalsePositionRepository.class);var prices=mock(BinanceFuturesClient.class);var closed=LaplaceInvertedFalsePositionEntity.builder().id("f").symbol("BTCUSDT").side(PositionSide.LONG).status(LaplacePositionStatus.CLOSED).netPnl(new BigDecimal("12.50")).leverage(15).build();when(f.findByStrategyAndStatus(any(),eq(LaplacePositionStatus.OPEN))).thenReturn(List.of());when(f.findByStrategyAndStatus(any(),eq(LaplacePositionStatus.CLOSED))).thenReturn(List.of(closed));var response=new LaplaceVariantApiService(t,f,prices,new LaplacePnlCalculator()).open(LaplacePaperVariant.INVERTED_FALSE);assertThat(response.totalPnlUsdt()).isEqualByComparingTo("12.50");assertThat(response.closedPositionsNetPnlUsdt()).isEqualByComparingTo("12.50");verifyNoInteractions(t,prices);}
}
